import "#nitro/virtual/polyfills";
import { useNitroApp } from "nitro/app";
import { handleLambdaEventWithStream } from "srvx/aws-lambda";
const nitroApp = useNitroApp();
const handler = awslambda.streamifyResponse((event, responseStream, context) => handleLambdaEventWithStream(nitroApp.fetch, event, responseStream, context));
export { handler };
